// PL-60: ZIP64 at the size boundary, from generated bytes (zip64-test-support.ts). Each case streams 4 GiB through the
// library's CRC-32, so the size and offset cases are two files, which Vitest runs in parallel.
import { describe, expect, it } from "vitest";

import { exportGenerated, MAX32 } from "./zip64-test-support.ts";

describe("PL-60: ZIP64 where a size needs it", () => {
  it("writes an entry of 0xFFFFFFFE bytes without ZIP64 sizes, and the next entry's offset with ZIP64", async () => {
    const read = await exportGenerated([
      { path: "a", size: MAX32 - 1 },
      { path: "index.html", size: 10 },
    ]);
    expect(read.entries.map((entry) => entry.zip64)).toEqual([false, true]);
    expect(read.offsets[1]).toBeGreaterThan(MAX32);
    expect(read.zip64).toBe(true);
  }, 120_000);

  it("writes an entry of 0xFFFFFFFF bytes with ZIP64 sizes", async () => {
    const read = await exportGenerated([
      { path: "a", size: MAX32 },
      { path: "index.html", size: 10 },
    ]);
    expect(read.entries.map((entry) => entry.zip64)).toEqual([true, true]);
    expect(read.zip64).toBe(true);
  }, 120_000);
});
